/**
 * Game content for the GitHub Pages edition, loaded from static JSON files
 * generated by scripts/build-pages-content.ts. Only the hosting browser
 * loads it; other players receive just what the game engines show them.
 */
import { GAMES, type GameId } from '../../shared/games.ts';
import { KIND_FOR_GAME } from '../../server/games/kinds.ts';
import type { ContentItem, ContentKind } from '../../server/games/types.ts';
import { asset } from '../lib/mode.ts';

interface BaseContent {
  categories: { slug: string; name: string; emoji: string }[];
  items: ContentItem[];
}
interface PictureContent {
  items: ContentItem[];
  images: Record<string, string>;
}

let basePromise: Promise<BaseContent> | null = null;
let picturePromise: Promise<PictureContent> | null = null;

async function getJson<T>(file: string): Promise<T> {
  const res = await fetch(asset(`content/${file}`), { cache: 'force-cache' });
  if (!res.ok) throw new Error(`content ${file}: HTTP ${res.status}`);
  return (await res.json()) as T;
}

export function loadBase(): Promise<BaseContent> {
  basePromise ??= getJson<BaseContent>('content.json').catch((e) => {
    basePromise = null;
    throw e;
  });
  return basePromise;
}
function loadPictures(): Promise<PictureContent> {
  picturePromise ??= getJson<PictureContent>('pictures.json').catch((e) => {
    picturePromise = null;
    throw e;
  });
  return picturePromise;
}

/** image id → data: URL, filled when picture pairs are picked */
export const imageUrls = new Map<string, string>();

function svgDataUrl(svg: string): string {
  const bytes = new TextEncoder().encode(svg);
  let bin = '';
  for (let i = 0; i < bytes.length; i += 0x8000) bin += String.fromCharCode(...bytes.subarray(i, i + 0x8000));
  return `data:image/svg+xml;base64,${btoa(bin)}`;
}

function shuffle<T>(a: T[]): T[] {
  const r = a.slice();
  for (let i = r.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [r[i], r[j]] = [r[j], r[i]];
  }
  return r;
}

/** Implements the part of ContentRepo that RoomManager uses. */
export class BrowserContent {
  async categoryNames(): Promise<Record<string, string>> {
    const b = await loadBase();
    return Object.fromEntries(b.categories.map((c) => [c.slug, c.name]));
  }

  async pick(opts: { kind: ContentKind; count: number; category?: string; difficulty?: string; exclude?: string[] }): Promise<ContentItem[]> {
    const isPicture = opts.kind === 'picture-pair';
    const all = isPicture ? (await loadPictures()).items : (await loadBase()).items.filter((i) => i.kind === opts.kind);
    let pool = all;
    if (opts.category && opts.category !== 'any') pool = pool.filter((i) => i.category === opts.category);
    if (opts.difficulty && opts.difficulty !== 'mixed') pool = pool.filter((i) => i.difficulty === opts.difficulty);
    const count = Math.max(1, Math.min(500, opts.count));
    const excluded = new Set(opts.exclude ?? []);
    const fresh = shuffle(pool.filter((i) => !excluded.has(i.id)));
    const picked = fresh.slice(0, count);
    if (picked.length < count) for (const i of shuffle(pool)) if (picked.length < count && !picked.includes(i)) picked.push(i);
    if (isPicture) {
      const { images } = await loadPictures();
      for (const p of picked) {
        const d = p.data as { a: string; b: string };
        for (const id of [d.a, d.b]) if (!imageUrls.has(id) && images[id]) imageUrls.set(id, svgDataUrl(images[id]));
      }
    }
    return picked.map((i) => ({ ...i, data: { ...i.data } }));
  }
}

/** Categories with item counts for the lobby's category picker. */
export async function categoriesFor(gameId: string | null) {
  const b = await loadBase();
  if (!gameId || !(gameId in GAMES)) return b.categories;
  const kind = KIND_FOR_GAME[gameId as GameId];
  const items = kind === 'picture-pair' ? (await loadPictures()).items : b.items.filter((i) => i.kind === kind);
  const counts = new Map<string, number>();
  for (const i of items) counts.set(i.category, (counts.get(i.category) ?? 0) + 1);
  return b.categories.filter((c) => counts.has(c.slug)).map((c) => ({ ...c, items: counts.get(c.slug) }));
}
